-- NexusTech — MySQL schema + seed data
-- Option A: import this file in phpMyAdmin, or run:
--   mysql -u root < database.sql
-- Option B (easier): just open setup.php in your browser — it does all of this automatically.

CREATE DATABASE IF NOT EXISTS nexustech CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE nexustech;

CREATE TABLE IF NOT EXISTS categories (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  slug VARCHAR(50) NOT NULL UNIQUE,
  label VARCHAR(80) NOT NULL,
  icon VARCHAR(16) NOT NULL DEFAULT '',
  tagline VARCHAR(160) NOT NULL DEFAULT ''
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS products (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  slug VARCHAR(120) NOT NULL UNIQUE,
  name VARCHAR(160) NOT NULL,
  brand VARCHAR(80) NOT NULL,
  category_id INT UNSIGNED NOT NULL,
  price DECIMAL(10,2) NOT NULL,
  old_price DECIMAL(10,2) NULL,
  rating DECIMAL(2,1) NOT NULL DEFAULT 4.5,
  reviews INT UNSIGNED NOT NULL DEFAULT 0,
  stock INT NOT NULL DEFAULT 0,
  badge VARCHAR(40) NULL,
  colors JSON NULL,
  short_desc VARCHAR(255) NOT NULL DEFAULT '',
  description TEXT NULL,
  specs JSON NULL,
  images JSON NULL,
  FOREIGN KEY (category_id) REFERENCES categories(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

